const row = $input.first().json;
let offset = Number(row.offset_value || 1);

const url = 'https://api.telegram.org/bot7818580465:AAH9aGFoeiw_Gd0NGAC4BqQngfeT0D7jOkk/getUpdates';

let resp;
try {
  resp = await this.helpers.httpRequest({
    method: 'GET',
    url: url + '?offset=' + offset + '&timeout=0&allowed_updates=' + encodeURIComponent(JSON.stringify(['callback_query'])),
    json: true,
    timeout: 10000
  });
} catch (e) {
  return [];
}

if (!resp || !resp.ok) return [];
const updates = resp.result || [];
if (!updates.length) return [];

return updates.map(u => ({ json: u }));

// ╨Ф╨╗╤П ╨║╨░╨╢╨┤╨╛╨│╨╛ update ╨▓╤Л╤В╨░╤Б╨║╨╕╨▓╨░╨╡╨╝ callback_query, video_id, action
const out = [];
for (const item of $input.all()) {
  const u = item.json;
  const cq = u.callback_query;
  if (!cq) continue;
  const data = String(cq.data || '');
  const parts = data.split(':');
  const action = parts[0] || '';
  const videoId = parts[1] || '';
  out.push({
    json: {
      update_id: u.update_id,
      video_id: videoId,
      action: action,
      callback_query_id: cq.id || null,
      message_id: (cq.message && cq.message.message_id) || null,
      chat_id: (cq.message && cq.message.chat && cq.message.chat.id) || null,
      payload: u
    }
  });
}
return out;

const extracted = $('Extract callbacks').all();
const out = [];
let maxId = 0;

for (let i = 0; i < extracted.length; i++) {
  const src = extracted[i].json;
  const looked = $input.all()[i] ? $input.all()[i].json : {};
  const topic = looked.channel_topic || null;
  out.push({
    json: {
      update_id: src.update_id,
      video_id: src.video_id,
      action: src.action,
      topic: topic,
      payload: src.payload
    }
  });
  if (src.update_id >= maxId) maxId = src.update_id + 1;
}

$getWorkflowStaticData('global').pendingOffset = maxId || 1;
return out;
